using System;using System.IO;using Mono.Cecil;
class VerifyPathWorkspace {static void Main(string[] args){var resolver=new DefaultAssemblyResolver();resolver.AddSearchDirectory(args.Length>2?args[2]:Path.GetDirectoryName(args[0]));using(var before=AssemblyDefinition.ReadAssembly(args[0],new ReaderParameters{AssemblyResolver=resolver}))using(var after=AssemblyDefinition.ReadAssembly(args[1])){int sites=PathWorkspacePatch.Reverse(before,after),methods,instructions;AssemblyStructure.RequireSame(before,after,out methods,out instructions);Console.WriteLine("Verified "+sites+" scoring map leases and exact restoration of "+methods+" methods / "+instructions+" instructions.");}}}
